# >>> CHOICES
_choice_host() {
    compgen -A hostname
}

_choice_interface() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
        return 0
    fi
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_module() {
    printf '%s\n' default icmp tcp tcpconn udp udplite dccp raw
    local dir
    for dir in /usr/lib/traceroute /usr/local/lib/traceroute /usr/libexec/traceroute /usr/lib/*/traceroute; do
        [[ -d "$dir" ]] || continue
        find "$dir" -mindepth 1 -maxdepth 1 -type f \( -name '*.so' -o -name '*.dylib' \) | sed 's|.*/||; s|\.so$||; s|\.dylib$||'
    done
}

_choice_protocol() {
    [[ -r /etc/protocols ]] || return 0
    gawk '!/^#/ && NF >= 2 { printf "%s\t%s\n", $1, $2 }' /etc/protocols
}

_choice_source() {
    if command -v ip >/dev/null 2>&1; then
        ip -o addr show 2>/dev/null | gawk '$3 == "inet" || ($3 == "inet6" && $4 !~ /^fe80:/) {
            split($4, a, "/")
            print a[1] "\t" $2
        }'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig 2>/dev/null | gawk '
            /^[^ \t]/ { iface = $1; sub(/:$/, "", iface) }
            $1 == "inet" { print $2 "\t" iface }
            $1 == "inet6" && $2 !~ /^fe80:/ { sub(/%.*$/, "", $2); print $2 "\t" iface }
        '
    fi
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
